import copy,json
from work import evaluate
requests=json.load(open('requests.json'))
evidence=json.load(open('evidence.json'))
policy=json.load(open('policy.json'))
actual=[evaluate(r,evidence,policy) for r in requests]
assert actual==json.load(open('report.json'))
# API inputs must be used and remain unchanged.
r={'claim':'c','conditions':{'z':1}}; e=[{'source':'old','claim':'c','value':7,'conditions':{'z':1},'verified':True},{'source':'new','claim':'c','value':8,'conditions':{'z':1},'verified':True,'supersedes':['old']}]; p={'required_conditions':['z'],'require_verified':True}
before=copy.deepcopy((r,e,p)); assert evaluate(r,e,p)=={'status':'supported','value':8,'sources':['new'],'unknowns':[]}; assert (r,e,p)==before
# Missing conditions, verification, false, conflicts, canonical objects, and absent calibration.
assert evaluate({'claim':'c','conditions':{}},e,p)=={'status':'unknown','value':None,'sources':[],'unknowns':['z']}
assert evaluate({'claim':'c','conditions':{'z':1}},[{'source':'u','claim':'c','value':9,'conditions':{'z':1},'verified':False}],p)=={'status':'unknown','value':None,'sources':[],'unknowns':['no matching evidence']}
assert evaluate({'claim':'b','conditions':{'z':1}},[{'source':'f','claim':'b','value':False,'conditions':{'z':1},'verified':True}],p)=={'status':'unsupported','value':False,'sources':['f'],'unknowns':[]}
ce=[{'source':'b','claim':'o','value':{'y':2,'x':1},'conditions':{'z':1},'verified':True},{'source':'a','claim':'o','value':{'x':1,'y':2},'conditions':{'z':1},'verified':True}]
assert evaluate({'claim':'o','conditions':{'z':1}},ce,p)=={'status':'supported','value':{'y':2,'x':1},'sources':['a','b'],'unknowns':[]}
ce.append({'source':'c','claim':'o','value':{'x':2},'conditions':{'z':1},'verified':True})
assert evaluate({'claim':'o','conditions':{'z':1}},ce,p)=={'status':'conflict','value':None,'sources':['a','b','c'],'unknowns':['source disagreement']}
assert evaluate({'claim':'cal','conditions':{'z':1}},[],p)=={'status':'unknown','value':None,'sources':[],'unknowns':['no matching evidence']}
assert all(set(x)=={'status','value','sources','unknowns'} for x in actual)
print('all checks passed')
